  "workSurface.widthRules": "スマート（デフォルト）: ワークスペースが 1 つなら内容に合わせ、2 つならウィンドウいっぱいに広げ、2 つの会話が最後にドラッグした比率で幅を分けます。内容に合わせる: 会話列とその{{shelf}}がそれぞれ自分の幅を保ち、まとめて中央に置かれ、両側にデスクトップが見えます。ウィンドウいっぱい: 列がウィンドウ全体の幅を分け合います。ここで設定するのは幅だけで、カードの角丸、隙間、影はそのままです（端まで表示は下で別に設定）。2 つのパネルの境界をドラッグすると、その 2 つだけが変わり、ダブルクリックでデフォルトに戻ります。フォーカスを移してもレイアウトは変わりません",
