  "settings.profileParity.modelDefaultHint": "新しい {{agent}} はこのデフォルト モデルを使用します。実行中の {{agent}} は選択を維持します。モデル カタログの編集は以下に個別に保存されます。",
  "settings.profileParity.runtimeModelDefault": "設定を解除し、実行時のデフォルトのモデルを使用します",
  "settings.profileParity.effortInheritance": "設定を解除すると、選択したモデルのデフォルトのエフォートに従います。明示的なプロファイル値は、カタログのデフォルト値よりも優先されます。以下の「保存」を使用して適用してください。",
  "settings.profileParity.effortUnknown": "カタログには、このモデルの推論レベルが記載されていません。保存された値を保持するか、クリアしてモデルのデフォルトを使用します。他のレベルはサポートされていないと想定されます。",
  "settings.profileParity.savedEffective": "ホストから返された保存された有効値",
  "settings.profileParity.limitsInheritance": "コンテキストの設定解除と圧縮はモデル カタログに従います。明示的なプロファイル値は、モデル制限内のカタログ値をオーバーライドします。以下の有効な値には、保存されていないドラフトは含まれません。",
  "settings.profileParity.catalogLimitsHint": "行には、保存された有効な値とホストから返されたソースが表示されます。コンテキストはモデルの最大値によって制限されます。圧縮では、プロファイル値、次にカタログ値、次にコンテキストの 90% が使用され、コンテキストの 90% が上限となります。",
  "settings.profileParity.modelEfforts": "推論: {levels}",
