  "settingsRisk.listen": "ホストのリスニング範囲を拡大する",
  "settingsRisk.listenHint": "ホスト · {host}: 新しいリスニング アドレス: {targets}。ホスト管理インターフェイスには、これらのネットワークからアクセスできます。認証は引き続き必要です。リスニングの変更は再起動後に適用されます。確認のため、ホスト名「{target}」を入力します。",
